{
  "checks": [
    {
      "problem": "每条问题与其修复动作分散在不同节里，编号体系也对不上，清单本身只有严重度标签和一句话描述，读者无法把某条问题直接对到它的修改动作，还可能漏掉最严重的那条。",
      "A": "部分解决",
      "B": "没解决"
    }
  ],
  "worse": [
    {
      "version": "B",
      "where": "问题清单",
      "why": "表里只有编号、问题、类型、位置、严重，比 A 少了「建议」列（和「影响」列）。读者看到 P2「浅色状态色上用白字」只知道问题是什么，要知道怎么改必须往下滚到「下一步」或「修复建议」，多一次翻找，而 A 在同一行就能看到改法。"
    },
    {
      "version": "B",
      "where": "下一步",
      "why": "五张卡片只有标题和整改建议，没有 P 编号，和上面的「问题清单」、中间的「修复建议」三处都只能用标题文字人工认对，派活或讨论时无法用编号互相指认；A 的卡片带 P1/P2/P3，和清单编号一一对应。"
    }
  ],
  "better": "A",
  "reason": "A 在问题清单里把每条问题的建议（和影响范围）直接放在同一行，并在「下一步」用 P1–P5 编号与清单一一对应，读者从某条问题到它的改法基本在同一节内完成；B 的清单仍是编号＋问题＋类型＋位置＋严重，改法只出现在页面更下方的「下一步」里，而且各处都没有编号可对，问题与整改动作仍要按标题自己认。",
  "next": [
    {
      "where": "问题清单 ↔ 修复建议",
      "task": "拿着 P2、P5 这类问题去找具体改法（改哪个色值、改成什么）",
      "why": "「修复建议」表按「位置」列行（辅助文字、警告文字、成功文字…），没有 P 编号，和清单的「位置」写法也对不上（P2 的位置是「成功、警告、危险按钮」）；P2 一条对应三行修复，P5 的实际改动在「背景」列（原色值和建议色值都是 #FFFFFF），读者要自己按颜色名拆条、还要意识到改的是背景色，来回对照多。"
    },
    {
      "where": "下一步",
      "task": "按顺序把全部问题排期、派活",
      "why": "只列了 3 条（01–03 对应 P1–P3），P4、P5 不在其中，读者会以为只有三件事要做，或者要回到问题清单再补一遍。"
    },
    {
      "where": "问题清单 P5 与 修复建议「主按钮悬停」",
      "task": "核对悬停按钮改动前后的对比度",
      "why": "清单写「对比度下降到 2.6」，修复建议写调整前 5.00、调整后 5.00，两处数值对不上，读者不知道以哪个为准，也无法判断这次修改是否解决了问题。"
    }
  ]
}
